try{$d=$env:BL_DIR;$k=$env:BL_KEEP;gci -LiteralPath $k -Recurse -File -Force -ErrorAction Stop|%{$t=Join-Path $d $_.FullName.Substring($k.Length+1);$null=md (Split-Path $t) -Force;Copy-Item -LiteralPath $_.FullName $t -Force -ErrorAction Stop};$null=New-Item -ItemType File -Force $env:BL_OK -ErrorAction Stop}catch{exit 1};exit 0
